probe(Array.isArray(slots.values) && slots.values.length > 0, "the logbook must hold at least one item");
probe(Number.isInteger(slots.threshold) && slots.threshold > 0, "the discard threshold must be a positive whole number of items");
probe(Number.isInteger(slots.target) && slots.target > 0, "the target node must be a positive whole number of items");
probe(Array.isArray(slots.nodes) && slots.nodes.length > 0, "the connectivity chain must name its nodes");
probe(slots.nodes.every((node) => Number.isInteger(node) && node > 0), "every node of the chain must be a positive whole number of items");
const remaining = slots.values.filter((value) => value < slots.threshold);
