let targetNode = slots.nodes.find((node) => node === slots.target);
probe(targetNode !== undefined, "the target node must appear in the logged chain");
const path = [];
let node = slots.nodes[0];
while (node !== targetNode) {
  const next = slots.nodes.filter((other) => other > node && other < slots.threshold);
  if (next.length === 0) { throw new Error("no known path between " + node + " and " + slots.target); }
  for (const other of next) {
    if (slots.nodes.indexOf(other) < slots.nodes.indexOf(node)) { continue; }
    const edge = slots.edges.get([node, other]);
    if (edge === undefined || edge.weight <= 0) { continue; }
    path.push({ to: other, weight: edge.weight });
    node = other;
  }
}
probe(path.length > 1, "the search must find a path between the first and the target node");
probe(path.every((step) => step.to > 0 && step.weight > 0), "every edge of the path must be a positive link");
